# Đề 1: đếm nguyên âm trong một chuỗi
def dem_nguyen_am(chu):
    dem = 0
    for c in chu:
        if c in "aeiou":
            dem = dem + 1
    return dem

print(dem_nguyen_am("python"))
print(dem_nguyen_am("khong co"))

